package com.picolas.openmusic;
import android.app.*;
import android.content.*;
import android.graphics.*;
import android.net.Uri;
import android.view.*;
import android.widget.*;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import org.junit.*;
import org.junit.runner.RunWith;
import java.io.*;
import java.lang.reflect.*;
import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class)
public class CustomizationDeviceTest {
    private final Instrumentation inst=InstrumentationRegistry.getInstrumentation();
    private Context context(){return inst.getTargetContext();}
    private MainActivity launch(){new LocalProfile(context()).finish();context().getSharedPreferences("app_updates",0).edit().putBoolean("enabled",false).commit();return (MainActivity)inst.startActivitySync(new Intent(context(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}
    private Object field(Object o,String name)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}
    private void navigate(MainActivity a)throws Exception{Method m=MainActivity.class.getDeclaredMethod("navigate",String.class);m.setAccessible(true);inst.runOnMainSync(()->{try{m.invoke(a,"profile");}catch(Exception e){throw new RuntimeException(e);}});inst.waitForIdleSync();}
    private void capture(MainActivity a,String name){inst.runOnMainSync(()->{View root=a.findViewById(android.R.id.content);Bitmap image=Bitmap.createBitmap(root.getWidth(),root.getHeight(),Bitmap.Config.ARGB_8888);root.draw(new Canvas(image));try(FileOutputStream out=new FileOutputStream(new File(context().getExternalFilesDir(null),name))){image.compress(Bitmap.CompressFormat.PNG,100,out);}catch(IOException e){throw new RuntimeException(e);}finally{image.recycle();}});}
    private View find(View v,String description){if(description.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View hit=find(g.getChildAt(i),description);if(hit!=null)return hit;}}return null;}
    private boolean hasPhoto(View v){if(v instanceof ImageView&&((ImageView)v).getDrawable() instanceof android.graphics.drawable.BitmapDrawable)return true;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)if(hasPhoto(g.getChildAt(i)))return true;}return false;}
    @Test public void photosTemplatesAndPortableProfilePersist()throws Exception{LocalProfile p=new LocalProfile(context());p.save("Picolas","Música para perderse un rato.",0);ProfileStyle style=ProfileStyle.preset(1);style.status="En mi mundo";style.about="✦  Indie · rock · noches largas  ✦";p.style(style);Bitmap image=Bitmap.createBitmap(640,240,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(image);Paint paint=new Paint();paint.setShader(new LinearGradient(0,0,640,240,0xff315681,0xff956ba9,Shader.TileMode.CLAMP));canvas.drawRect(0,0,640,240,paint);File source=new File(context().getCacheDir(),"profile-source.png");try(FileOutputStream out=new FileOutputStream(source)){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();String portrait=ProfileImages.copy(context(),Uri.fromFile(source),false),banner=ProfileImages.copy(context(),Uri.fromFile(source),true);p.image(false,portrait);p.image(true,banner);assertTrue(p.saveTemplate("Mi noche",style));int last=p.templates().length()-1;p.style(ProfileStyle.preset(2));p.image(false,"");p.applyTemplate(last);assertEquals(style.background,new LocalProfile(context()).style().background);assertEquals(portrait,p.image(false));
        ProfileShare.Snapshot shared=ProfileShare.snapshot(p,MusicStore.get(context()));shared.portrait=ProfileImages.export(context(),portrait);shared.banner=ProfileImages.export(context(),banner);ProfileShare.Snapshot decoded=ProfileShare.parse(ProfileShare.json(shared));assertFalse(ProfileImages.embedded(decoded.banner).isEmpty());assertTrue(ProfileShare.decode(ProfileShare.qr(shared)).portrait.isEmpty());ProfileStyle hidden=p.style();hidden.showPlaylists=false;p.style(hidden);assertTrue(ProfileShare.snapshot(p,MusicStore.get(context())).playlists.isEmpty());p.style(style);
        MainActivity a=launch();try{navigate(a);java.util.concurrent.atomic.AtomicBoolean loaded=new java.util.concurrent.atomic.AtomicBoolean();long end=System.currentTimeMillis()+15000;while(!loaded.get()&&System.currentTimeMillis()<end){inst.runOnMainSync(()->loaded.set(hasPhoto(a.findViewById(android.R.id.content))));if(!loaded.get())Thread.sleep(100);}assertTrue(loaded.get());capture(a,"profile-custom.png");p.image(false,"");p.image(true,"");p.style(ProfileStyle.preset(3));navigate(a);capture(a,"profile-cafe.png");}finally{inst.runOnMainSync(a::finish);p.deleteTemplate(last);source.delete();}}
    @Test public void editorCancelSaveAndUpdatePrompt()throws Exception{LocalProfile p=new LocalProfile(context());p.save("Antes","Descripción",0);MainActivity a=launch();try{SocialScreens social=(SocialScreens)field(a,"social");inst.runOnMainSync(social::editProfile);AlertDialog editor=(AlertDialog)field(social.studio,"editor");inst.runOnMainSync(()->{((EditText)find(editor.getWindow().getDecorView(),"Nombre")).setText("Descartado");editor.getButton(AlertDialog.BUTTON_NEGATIVE).performClick();});inst.waitForIdleSync();assertEquals("Antes",p.name());inst.runOnMainSync(social::editProfile);AlertDialog saved=(AlertDialog)field(social.studio,"editor");inst.runOnMainSync(()->{((EditText)find(saved.getWindow().getDecorView(),"Nombre")).setText("Nuevo nombre");((EditText)find(saved.getWindow().getDecorView(),"Estado o frase")).setText("Mi estado");saved.getButton(AlertDialog.BUTTON_POSITIVE).performClick();});inst.waitForIdleSync();assertEquals("Nuevo nombre",p.name());assertEquals("Mi estado",p.style().status);
        AppUpdates updates=(AppUpdates)field(a,"updates");String data="{\"tag_name\":\"v9.0.0\",\"assets\":[{\"name\":\"Open-Music-9.0.0.apk\",\"state\":\"uploaded\",\"size\":9000000,\"browser_download_url\":\"https://github.com/picolasYT/Open-Music/releases/download/v9.0.0/Open-Music-9.0.0.apk\"}]}";UpdateRelease release=UpdateRelease.parse(data,updates.current());inst.runOnMainSync(()->updates.offer(release,true));AlertDialog prompt=(AlertDialog)field(updates,"prompt");assertTrue(prompt.isShowing());inst.runOnMainSync(()->prompt.getButton(AlertDialog.BUTTON_NEUTRAL).performClick());inst.waitForIdleSync();assertEquals("9.0.0",context().getSharedPreferences("app_updates",0).getString("skipped",""));inst.runOnMainSync(()->updates.offer(release,false));assertFalse(prompt.isShowing());
    }finally{inst.runOnMainSync(a::finish);}}
    @Test public void illustratedGuideNavigatesAndProfileFitsSmallScreens()throws Exception{
        MainActivity a=launch();try{SocialScreens social=(SocialScreens)field(a,"social");inst.runOnMainSync(social::tutorial);AlertDialog guide=(AlertDialog)field(social,"wizard");inst.waitForIdleSync();
            for(int step=0;step<6;step++){final int index=step;inst.runOnMainSync(()->{assertTrue(guide.isShowing());View root=guide.getWindow().getDecorView();Bitmap bitmap=Bitmap.createBitmap(root.getWidth(),root.getHeight(),Bitmap.Config.ARGB_8888);root.draw(new Canvas(bitmap));try(FileOutputStream out=new FileOutputStream(new File(context().getExternalFilesDir(null),"guide-"+index+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}catch(IOException e){throw new RuntimeException(e);}bitmap.recycle();if(index==1){guide.getButton(AlertDialog.BUTTON_NEUTRAL).performClick();assertEquals(View.INVISIBLE,guide.getButton(AlertDialog.BUTTON_NEUTRAL).getVisibility());guide.getButton(AlertDialog.BUTTON_POSITIVE).performClick();}guide.getButton(AlertDialog.BUTTON_POSITIVE).performClick();});inst.waitForIdleSync();}assertFalse(guide.isShowing());
            inst.runOnMainSync(()->{android.content.res.Configuration config=new android.content.res.Configuration(a.getResources().getConfiguration());config.fontScale=1.5f;Context large=a.createConfigurationContext(config);TextView button=Ui.button(large,"Personalizar perfil y guardar mi diseño",()->{});button.measure(View.MeasureSpec.makeMeasureSpec(Ui.dp(large,240),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));assertTrue(button.getMeasuredHeight()>=Ui.dp(large,52));assertEquals(0,button.getLayout().getEllipsisCount(0));
                for(int preset=0;preset<8;preset++){ProfileStyle style=ProfileStyle.preset(preset);View card=social.studio.card("Nombre largo para probar el perfil","Una presentación que ocupa varias líneas y debe mantenerse legible.",style,"","","12 playlists · 24 favoritos");card.measure(View.MeasureSpec.makeMeasureSpec(Ui.dp(a,240),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));card.layout(0,0,card.getMeasuredWidth(),card.getMeasuredHeight());View avatar=find(card,"Foto de perfil de Nombre largo para probar el perfil");assertNotNull(avatar);android.graphics.Rect bounds=new android.graphics.Rect(0,0,avatar.getWidth(),avatar.getHeight());((ViewGroup)card).offsetDescendantRectToMyCoords(avatar,bounds);assertTrue(bounds.top>=0);assertTrue(bounds.right<=card.getWidth());assertTrue(bounds.bottom<card.getHeight());}
            });
        }finally{inst.runOnMainSync(a::finish);}
    }
    @Test public void automaticCheckPromptsAndThrottlesOverHttps()throws Exception{
        MainActivity a=launch();okhttp3.mockwebserver.MockWebServer server=new okhttp3.mockwebserver.MockWebServer();
        okhttp3.tls.HeldCertificate certificate=new okhttp3.tls.HeldCertificate.Builder().addSubjectAlternativeName("localhost").build();
        okhttp3.tls.HandshakeCertificates serverTls=new okhttp3.tls.HandshakeCertificates.Builder().heldCertificate(certificate).build(),clientTls=new okhttp3.tls.HandshakeCertificates.Builder().addTrustedCertificate(certificate.certificate()).build();
        server.useHttps(serverTls.sslSocketFactory(),false);server.start();okhttp3.OkHttpClient client=new okhttp3.OkHttpClient.Builder().sslSocketFactory(clientTls.sslSocketFactory(),clientTls.trustManager()).build();
        org.json.JSONObject release=new org.json.JSONObject().put("tag_name","v9.1.0").put("assets",new org.json.JSONArray().put(new org.json.JSONObject().put("name","Open-Music-9.1.0.apk").put("state","uploaded").put("size",9000000).put("browser_download_url",UpdateRelease.RELEASES+"/download/v9.1.0/Open-Music-9.1.0.apk")));
        server.enqueue(new okhttp3.mockwebserver.MockResponse().setBody(release.toString()));context().getSharedPreferences("app_updates",0).edit().clear().commit();AppUpdates updates=new AppUpdates(a,client,server.url("/latest").toString());
        try{inst.runOnMainSync(updates::resume);assertNotNull(server.takeRequest(10,java.util.concurrent.TimeUnit.SECONDS));long end=System.currentTimeMillis()+15000;java.util.concurrent.atomic.AtomicReference<AlertDialog> dialog=new java.util.concurrent.atomic.AtomicReference<>();while(dialog.get()==null&&System.currentTimeMillis()<end){inst.runOnMainSync(()->{try{dialog.set((AlertDialog)field(updates,"prompt"));}catch(Exception e){throw new RuntimeException(e);}});if(dialog.get()==null)Thread.sleep(50);}assertNotNull("A newer stable release must prompt automatically",dialog.get());inst.runOnMainSync(()->dialog.get().getButton(AlertDialog.BUTTON_NEGATIVE).performClick());inst.waitForIdleSync();assertEquals("9.1.0",context().getSharedPreferences("app_updates",0).getString("snoozed",""));inst.runOnMainSync(()->{updates.pause();updates.resume();});assertEquals(1,server.getRequestCount());
        }finally{inst.runOnMainSync(()->{updates.close();a.finish();});server.shutdown();}
    }
}
